import {specimens,posters,naturePlates} from './specimens.js';
export function createGallery(api){
 const card=(id,s,i)=>`<button class="model-card specimen-card ${id}-model-card ${i===0?'specimen-featured':''}" data-action="model" data-model="${id}"><span class="model-card-label">MẪU VẬT ${String(i+1).padStart(2,'0')}<span>LỚP ${s.grade}</span></span><span class="specimen-display"><span class="specimen-display-ring"></span><img class="specimen-render" src="assets/${s.image}" alt="Mô hình minh họa ${s.title}" loading="lazy"></span><span class="model-card-bottom"><span class="specimen-card-caption"><span>${s.category}</span><strong>${s.title}</strong><span>${s.subtitle}</span></span><span class="round-button">${api.icon('arrow-up-right')}</span></span></button>`;
 const plates=()=>`<div class="nature-plates">${naturePlates.map(p=>`<button class="nature-plate" data-nature="${p.id}"><img src="assets/${p.image}" alt="${p.title}" loading="lazy"><span><small>${p.kicker}</small><strong>${p.title}</strong><span>${api.icon('arrow-up-right')}</span></span></button>`).join('')}</div>`;
 function render(){
  document.querySelector('#library-model-grid').innerHTML=Object.entries(specimens).map(([id,s],i)=>card(id,s,i)).join('');
  document.querySelector('#poster-gallery').innerHTML=posters.map(p=>`<article class="science-poster-card"><button class="science-poster-image" data-poster="${p.id}" aria-label="Mở poster ${p.title}"><img src="assets/${p.image}" alt="Poster khoa học: ${p.title}" loading="lazy"><span>${api.icon('plus')}</span></button><div><span class="eyebrow">${p.kicker}</span><h3>${p.title}</h3><p>${p.description}</p><button class="text-button" data-poster="${p.id}">Mở bản trưng bày ${api.icon('arrow-up-right')}</button></div></article>`).join('');
  document.querySelectorAll('[data-nature-gallery]').forEach(el=>el.innerHTML=plates());
 }
 function openPoster(id){const p=posters.find(x=>x.id===id);if(!p)return;api.showDialog(p.title,p.kicker,`<div class="poster-view"><img src="assets/${p.image}" alt="${p.title}"><div><p>${p.description}</p><a class="button button-dark" href="assets/${p.image}" download="VNScape-poster-${p.id}.svg">Tải poster SVG ${api.icon('download')}</a><button class="text-button" data-action="lesson" data-id="${p.lesson}">Khám phá bài học ${api.icon('arrow-right')}</button><p class="privacy-note">Poster do VNScape thiết kế. Hình ảnh và sơ đồ minh họa không theo tỉ lệ thực.</p></div></div>`,'poster')}
 function openNature(id){const p=naturePlates.find(x=>x.id===id);if(!p)return;api.showDialog(p.title,p.kicker,`<figure class="nature-photo-view"><img src="assets/${p.image}" alt="${p.title}"><figcaption><p>${p.question}</p><a href="${p.source}" target="_blank" rel="noopener">Ảnh: ${p.credit} ↗</a></figcaption></figure><button class="button button-dark" data-action="lesson" data-id="${p.lesson}">Kết nối với bài học ${api.icon('arrow-right')}</button>`,'nature')}
 document.addEventListener('click',e=>{const poster=e.target.closest('[data-poster]');if(poster)openPoster(poster.dataset.poster);const nature=e.target.closest('[data-nature]');if(nature)openNature(nature.dataset.nature)});
 for(const el of document.querySelectorAll('.ambient-exhibition')){el.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=el.getBoundingClientRect();el.style.setProperty('--scene-x',((e.clientX-r.left)/r.width-.5).toFixed(3));el.style.setProperty('--scene-y',((e.clientY-r.top)/Math.min(r.height,1000)-.5).toFixed(3))});el.addEventListener('pointerleave',()=>{el.style.setProperty('--scene-x',0);el.style.setProperty('--scene-y',0)})}
 render();return {render};
}
